// Normalizadores auxiliares
function normalizeArray(value) {
  if (!value) return [];
  if (Array.isArray(value)) return value.map(String).map(v => v.trim()).filter(Boolean);
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (!trimmed) return [];
    try {
      const parsed = JSON.parse(trimmed);
      if (Array.isArray(parsed)) return normalizeArray(parsed);
    } catch (error) {
      // ignore
    }
    return trimmed.split(/,|\n/).map(part => part.trim()).filter(Boolean);
  }
  return [];
}

function parseJson(value) {
  if (!value) return {};
  if (typeof value === 'object') return value;
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (!trimmed) return {};
    try {
      return JSON.parse(trimmed);
    } catch (error) {
      return {};
    }
  }
  return {};
}

function normalizeSources(list) {
  const sources = Array.isArray(list) ? list : normalizeArray(list);
  return sources.map(source => {
    if (typeof source === 'string') {
      return {
        Nombre: source,
        Cita: source,
        URL: null,
        Tipo: null,
        Notas: null
      };
    }
    if (source && typeof source === 'object') {
      return {
        Nombre: source.Nombre || source.nombre || source.Cita || source.cita || '',
        Cita: source.Cita || source.cita || source.Nombre || source.nombre || '',
        URL: source.URL || source.url || null,
        Tipo: source.Tipo || source.tipo || null,
        Notas: source.Notas || source.notas || null
      };
    }
    return { Nombre: '', Cita: '', URL: null, Tipo: null, Notas: null };
  });
}

