    prompt_payload: context,
    prompt: prompt
  }
}];

let response = $json?.message?.content ?? $json?.text ?? $json?.response ?? '';
response = String(response).trim().replace(/
/g, '
');
const fenceMatch = response.match(/^```(\w+)?\s*
([\s\S]*?)
```$/);
if (fenceMatch) {
  response = fenceMatch[2].trim();
} else {
  if (response.startsWith('```')) response = response.replace(/^```\s*
?/, '');
  if (response.endsWith('```')) response = response.replace(/
?```\s*$/, '');
  response = response.trim();
}
const src = ($items('Construir Prompt Redaccion Investigada', 0)[$itemIndex]?.json) ?? {};
return [{
