const markdown = String($json.raw_markdown || '').replace(/
/g, '
');
const fm = markdown.match(/^---
([\s\S]*?)
---
([\s\S]*)$/);
let front = '', content = markdown;
if (fm) {
  front = fm[1].trim();
  content = fm[2] ?? '';
}
const meta = {};
if (front) {
  const lines = front.split('
');
  let currentKey = null;
  for (const raw of lines) {
    const line = raw.trim();
    if (!line) continue;
    const kv = line.match(/^([A-Za-z0-9 _-]+)\s*:\s*(.*)$/);
    if (kv) {
      currentKey = kv[1].toLowerCase().trim();
      meta[currentKey] = kv[2];
      continue;
    }
    const li = line.match(/^-\s+(.*)$/);
    if (li && currentKey) {
      const prev = meta[currentKey] || '';
      meta[currentKey] = (prev ? prev + '
' : '') + li[1];
      continue;
    }
    if (currentKey) {
      meta[currentKey] = (meta[currentKey] ? meta[currentKey] + '
' : '') + line;
    }
  }
}
const get = k => meta[k] || meta[k.replace(/\s+/g, '')] || '';
let metaTitle = get('meta title') || get('title') || '';
let metaDescription = get('meta description') || get('description') || '';
let tagsRaw = get('tags');
let tags = [];
if (tagsRaw) {
  const normalized = tagsRaw.replace(/^\[/, '').replace(/\]$/, '').split(/
|,/);
  tags = normalized.map(t => t.trim()).filter(Boolean);
}
const h1 = content.match(/^#\s+(.+)\s*$/m);
const title = (h1 && h1[1].trim()) || metaTitle || ($json.idea_title || '').trim();
const clamp = (s, n) => (s.length <= n ? s : s.slice(0, n - 1).trimEnd() + '…');
if (!metaTitle) metaTitle = clamp(title || 'Sin titulo', 60);
if (!metaDescription) {
  const plain = content.replace(/^---[\s\S]*?---
/, '')
    .replace(/^#+\s+.*$/gm, '')
    .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')
    .replace(/[*_~`#>]/g, '')
    .replace(/
{2,}/g, '
')
    .trim();
  const firstPara = plain.split('
').find(p => p.trim());
  metaDescription = clamp(firstPara || 'Articulo generado automaticamente.', 160);
}
return [{
  json: {
    ...$json,
    title: title || 'Sin titulo',
    meta_title: metaTitle,
    meta_description: metaDescription,
    tags: Array.isArray(tags) ? tags : [],
    content_markdown: content.trim(),
    raw_markdown: markdown
  }
}];

let idea_id = $json.idea_id;
let keyword_cluster_id = $json.keyword_cluster_id;
