const fromPrompt = $items('Construir Prompt Redaccion Investigada', 0)[idx]?.json || {};
const fromParse = $items('Parse Markdown Response', 0)[idx]?.json || {};
const fromMeta = $items('Extraer Metadatos', 0)[idx]?.json || {};
idea_id = idea_id || fromMeta.idea_id || fromParse.idea_id || fromPrompt.idea_id;
keyword_cluster_id = keyword_cluster_id || fromMeta.keyword_cluster_id || fromParse.keyword_cluster_id || fromPrompt.keyword_cluster_id;
const hasContent = typeof $json.content_markdown === 'string' && $json.content_markdown.trim().length > 0;
let word_count = 0;
if (hasContent) {
